window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d80d80c7f7873f94"]={"versions": [{"id": "FIG-d80d80c7f7873f94", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticAccessPermission</code>:</strong> Spezifiziert Zugriffsbedingungen (Sitzungszustände / <em>DiagnosticSessions</em>, Sicherheitsstufen / <em>SecurityLevels</em>).</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li>Attribut: <code>accessPermissionValidity: DiagnosticAccessPermissionValidityEnum</code> (steuert, ob Berechtigungen serviceübergreifend auf Klassenebene oder instancespezifisch geprüft werden).</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribut: <code>«atpVariation» +id: PositiveInteger</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong>Subfunktionselemente (<code>Identifiable</code>):</strong> Bilden die drei UDS-Subfunktionen ab:</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>).</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>).</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>).</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Parameterträger für Nutzdatenfelder im Request-/Response-Frame.</li>\n<li>Attribut: <code>+bitOffset: PositiveInteger</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads).</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>Identifiable</code>):</strong> Typdefinition des Dateninhalts.</li>\n<li>Attribute:</li>\n<li><code>+arraySizeSemantics: ArraySizeSemanticsEnum [0..1]</code> (z. B. <code>fixedSize</code>, <code>variableSize</code>).</li>\n<li><code>+maxNumberOfElements: PositiveInteger [0..1]</code> (Obergrenze bei dynamischen Datenfeldern).</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>1</code> (<code>+routine</code>), referenziert die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert ausschließlich <code>+response 0..*</code> (gemäß UDS-Definition akzeptiert Subfunktion <code>0x03</code> keine Request-Control-Option-Records).</li>\n<li><strong><code>DiagnosticParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> (ermöglicht modulare Modellaufteilung über Dateigrenzen und Variantenbildung zur Compile-/Pre-Compile-Time).</li>\n<li><strong>Security & Session (<code>+accessPermission</code>):</strong></li>\n<li>Assoziation <code>0..1</code> von <code>DiagnosticServiceClass</code> sowie <code>0..1</code> von <code>DiagnosticServiceInstance</code> auf <code>DiagnosticAccessPermission</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}, {"id": "FIG-67fbdcbf06dacca7", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li>Attribut: <code>accessPermissionValidity: DiagnosticAccessPermissionValidityEnum</code> (steuert, ob Berechtigungen serviceübergreifend auf Klassenebene oder instancespezifisch geprüft werden).</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribute:</li>\n<li><code>+routineInfo: PositiveInteger [0..1]</code> (Referenzierung zusätzlicher Routineninformationen).</li>\n<li><code>«atpVariation» +id: PositiveInteger</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong><code>DiagnosticRoutineSubfunction</code>:</strong> Gemeinsame Basisklasse der UDS-Subfunktionen für RoutineControl.</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Parameterträger für Nutzdatenfelder im Request-/Response-Frame.</li>\n<li>Attribut: <code>+bitOffset: PositiveInteger</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads).</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>Identifiable</code>):</strong> Typdefinition des Dateninhalts.</li>\n<li>Attribute:</li>\n<li><code>+arraySizeSemantics: ArraySizeSemanticsEnum [0..1]</code> (z. B. <code>fixedSize</code>, <code>variableSize</code>).</li>\n<li><code>+maxNumberOfElements: PositiveInteger [0..1]</code> (Obergrenze bei dynamischen Datenfeldern).</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>1</code> (<code>+routine</code>), referenziert die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert ausschließlich <code>+response 0..*</code>.</li>\n<li><strong><code>DiagnosticParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> (ermöglicht modulare Modellaufteilung über Dateigrenzen und Variantenbildung zur Compile-/Pre-Compile-Time).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}, {"id": "FIG-f4c1bc1c43c7d939", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li>Attribut: <code>accessPermissionValidity: DiagnosticAccessPermissionValidityEnum</code> (steuert, ob Berechtigungen serviceübergreifend auf Klassenebene oder instancespezifisch geprüft werden).</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribute:</li>\n<li><code>+routineInfo: PositiveInteger [0..1]</code> (Referenzierung zusätzlicher Routineninformationen).</li>\n<li><code>«atpVariation» +id: PositiveInteger</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong><code>DiagnosticRoutineSubfunction</code>:</strong> Gemeinsame Basisklasse der UDS-Subfunktionen für RoutineControl.</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Parameterträger für Nutzdatenfelder im Request-/Response-Frame.</li>\n<li>Attribut: <code>+bitOffset: PositiveInteger</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads).</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>Identifiable</code>):</strong> Typdefinition des Dateninhalts.</li>\n<li>Attribute:</li>\n<li><code>+arraySizeSemantics: ArraySizeSemanticsEnum [0..1]</code> (z. B. <code>fixedSize</code>, <code>variableSize</code>).</li>\n<li><code>+maxNumberOfElements: PositiveInteger [0..1]</code> (Obergrenze bei dynamischen Datenfeldern).</li>\n<li><code>+scalingInfoSize: PositiveInteger [0..1]</code> (Größe der Skalierungsinformation in Bytes).</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>1</code> (<code>+routine</code>), referenziert die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><strong><code>DiagnosticParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> (ermöglicht modulare Modellaufteilung über Dateigrenzen und Variantenbildung zur Compile-/Pre-Compile-Time).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}, {"id": "FIG-e97877f6c18b29d1", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>0..1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribute:</li>\n<li><code>+routineInfo: PositiveInteger [0..1]</code> (Referenzierung zusätzlicher Routineninformationen).</li>\n<li><code>«atpVariation» +id: PositiveInteger [0..1]</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong><code>DiagnosticRoutineSubfunction</code>:</strong> Gemeinsame Basisklasse der UDS-Subfunktionen für RoutineControl.</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Parameterträger für Nutzdatenfelder im Request-/Response-Frame.</li>\n<li>Attribut: <code>«atpIdentityContributor» +bitOffset: PositiveInteger [0..1]</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads; dient als Identitätsbeitrag).</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>Identifiable</code>):</strong> Typdefinition des Dateninhalts.</li>\n<li>Attribute:</li>\n<li><code>+arraySizeSemantics: ArraySizeSemanticsEnum [0..1]</code> (z. B. <code>fixedSize</code>, <code>variableSize</code>).</li>\n<li><code>+maxNumberOfElements: PositiveInteger [0..1]</code> (Obergrenze bei dynamischen Datenfeldern).</li>\n<li><code>+scalingInfoSize: PositiveInteger [0..1]</code> (Größe der Skalierungsinformation in Bytes).</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>1</code> (<code>+routine</code>), referenziert die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><strong><code>DiagnosticParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>0..1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> und annotiert mit Tag <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}, {"id": "FIG-0fe370724b3d43d5", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>0..1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribute:</li>\n<li><code>+routineInfo: PositiveInteger [0..1]</code> (Referenzierung zusätzlicher Routineninformationen).</li>\n<li><code>«atpVariation» +id: PositiveInteger [0..1]</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong><code>DiagnosticRoutineSubfunction</code>:</strong> Gemeinsame Basisklasse der UDS-Subfunktionen für RoutineControl.</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Parameterträger für Nutzdatenfelder im Request-/Response-Frame.</li>\n<li>Attribut: <code>«atpIdentityContributor» +bitOffset: PositiveInteger [0..1]</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads; dient als Identitätsbeitrag).</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>Identifiable</code>):</strong> Typdefinition des Dateninhalts ohne eigene Attributspezifikation im Klassenkörper.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>1</code> (<code>+routine</code>), referenziert die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><strong><code>DiagnosticParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>0..1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> und annotiert mit Tag <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}, {"id": "FIG-cd0e7a48104744c7", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>0..1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribute:</li>\n<li><code>+routineInfo: PositiveInteger [0..1]</code> (Referenzierung zusätzlicher Routineninformationen).</li>\n<li><code>«atpVariation» +id: PositiveInteger [0..1]</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong><code>DiagnosticRoutineSubfunction</code>:</strong> Gemeinsame Basisklasse der UDS-Subfunktionen für RoutineControl.</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticAbstractParameter</code>:</strong> Abstrakte Basisklasse für Diagnose-Parameter.</li>\n<li>Attribute:</li>\n<li><code>+parameterSize: PositiveInteger [0..1]</code> (Größe des Parameters).</li>\n<li><code>«atpIdentityContributor» +bitOffset: PositiveInteger [0..1]</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads; dient als Identitätsbeitrag).</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Konkrete Spezialisierung von <code>DiagnosticAbstractParameter</code> als Träger für Request- und Response-Parameter der Subfunktionen.</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>DiagnosticServiceMappingDiagTarget</code>, <code>Identifiable</code>):</strong> Typdefinition des Dateninhalts, implementiert sowohl <code>DiagnosticServiceMappingDiagTarget</code> als auch <code>Identifiable</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>0..1</code> (<code>+routine</code>), referenziert optional die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><strong><code>DiagnosticAbstractParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>0..1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> und annotiert mit Tag <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}, {"id": "FIG-f0110b9ca2edc883", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>0..1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribute:</li>\n<li><code>+routineInfo: PositiveInteger [0..1]</code> (Referenzierung zusätzlicher Routineninformationen).</li>\n<li><code>«atpVariation» +id: PositiveInteger [0..1]</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong><code>DiagnosticRoutineSubfunction</code>:</strong> Gemeinsame Basisklasse der UDS-Subfunktionen für RoutineControl.</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticAbstractParameter</code>:</strong> Abstrakte Basisklasse für Diagnose-Parameter.</li>\n<li>Attribute:</li>\n<li><code>+parameterSize: PositiveInteger [0..1]</code> (Größe des Parameters).</li>\n<li><code>«atpIdentityContributor» +bitOffset: PositiveInteger [0..1]</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads; dient als Identitätsbeitrag).</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Konkrete Spezialisierung von <code>DiagnosticAbstractParameter</code> als Träger für Request- und Response-Parameter der Subfunktionen.</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>DiagnosticServiceMappingDiagTarget</code>, <code>Identifiable</code>):</strong> Typdefinition des Dateninhalts, implementiert sowohl <code>DiagnosticServiceMappingDiagTarget</code> als auch <code>Identifiable</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>0..1</code> (<code>+routine</code>), referenziert optional die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><strong><code>DiagnosticAbstractParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>0..1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> und annotiert mit Tag <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}, {"id": "FIG-2fccf97431013370", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>0..1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribute:</li>\n<li><code>+routineInfo: PositiveInteger [0..1]</code> (Referenzierung zusätzlicher Routineninformationen).</li>\n<li><code>«atpVariation» +id: PositiveInteger [0..1]</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong><code>DiagnosticRoutineSubfunction</code>:</strong> Gemeinsame Basisklasse der UDS-Subfunktionen für RoutineControl.</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticAbstractParameter</code>:</strong> Abstrakte Basisklasse für Diagnose-Parameter.</li>\n<li>Attribute:</li>\n<li><code>+parameterSize: PositiveInteger [0..1]</code> (Größe des Parameters).</li>\n<li><code>«atpIdentityContributor» +bitOffset: PositiveInteger [0..1]</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads; dient als Identitätsbeitrag).</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Konkrete Spezialisierung von <code>DiagnosticAbstractParameter</code> als Träger für Request- und Response-Parameter der Subfunktionen.</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>DiagnosticServiceMappingDiagTarget</code>, <code>Identifiable</code>):</strong> Typdefinition des Dateninhalts, implementiert sowohl <code>DiagnosticServiceMappingDiagTarget</code> als auch <code>Identifiable</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>0..1</code> (<code>+routine</code>), referenziert optional die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><strong><code>DiagnosticAbstractParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>0..1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> und annotiert mit Tag <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}, {"id": "FIG-7a3bd921c1b98c1c", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt aus der AUTOSAR-Spezifikation des <em>Diagnostic Extract Template</em> / DEXT).</li>\n<li><strong>Technischer Zweck:</strong> Formale Beschreibung des UDS-Dienstes <em>RoutineControl</em> (Service-ID <code>0x31</code> nach ISO 14229-1). Das Metamodell standardisiert den Austausch diagnostischer Routinen-Definitionen zwischen OEM und Zulieferer zur automatisierten Parametrierung des BSW-Diagnosestacks (primär <em>Diagnostic Communication Manager</em> / DCM) und der Generierung der Applikationsschnittstellen (RTE / SW-C).</li>\n<li><strong>Funktionale Einordnung:</strong> Brücke zwischen Diagnosespezifikation (ODX/DEXT) und AUTOSAR-BswM/Dcm-Konfiguration (Classic Platform: <code>DcmDspRoutine</code>, Adaptive Platform: <code>ara::diag::Routine</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Klassenhierarchie</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticCommonElement</code>:</strong> Abstrakte Basisklasse aller exportier- und wiederverwendbaren Diagnose-Artefakte im DEXT.</li>\n<li><strong><code>DiagnosticServiceClass</code>:</strong> Definiert allgemeingültige Service-Eigenschaften.</li>\n<li><strong><code>DiagnosticRoutineControlClass</code>:</strong> Spezialisierung von <code>DiagnosticServiceClass</code> für Service <code>0x31</code>.</li>\n<li><strong><code>DiagnosticServiceInstance</code>:</strong> Repräsentiert eine konkrete Instanz eines Services auf einem diagnostischen Port / Protokoll.</li>\n<li><strong><code>DiagnosticRoutineControl</code>:</strong> Spezialisierung von <code>DiagnosticServiceInstance</code> für RoutineControl. Redefiniert die Relation <code>serviceClass</code> (<code>0..1</code>, <code>{redefines serviceClass}</code>) auf <code>DiagnosticRoutineControlClass</code>.</li>\n<li><strong><code>DiagnosticRoutine</code>:</strong> Repräsentiert eine spezifische Diagnose-Routine.</li>\n<li>Attribute:</li>\n<li><code>+routineInfo: PositiveInteger [0..1]</code> (Referenzierung zusätzlicher Routineninformationen).</li>\n<li><code>«atpVariation» +id: PositiveInteger [0..1]</code> (definiert den 16-Bit Routine Identifier / RID gemäß ISO 14229-1; unterstützt AUTOSAR-Variantenbildung).</li>\n<li><strong><code>DiagnosticRoutineSubfunction</code>:</strong> Gemeinsame Basisklasse der UDS-Subfunktionen für RoutineControl.</li>\n<li><strong><code>DiagnosticStartRoutine</code>:</strong> Subfunktion <code>0x01</code> (<em>startRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticStopRoutine</code>:</strong> Subfunktion <code>0x02</code> (<em>stopRoutine</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticRequestRoutineResults</code>:</strong> Subfunktion <code>0x03</code> (<em>requestRoutineResults</em>), spezialisiert <code>DiagnosticRoutineSubfunction</code>.</li>\n<li><strong><code>DiagnosticAbstractParameter</code>:</strong> Abstrakte Basisklasse für Diagnose-Parameter.</li>\n<li>Attribute:</li>\n<li><code>+parameterSize: PositiveInteger [0..1]</code> (Größe des Parameters).</li>\n<li><code>«atpIdentityContributor» +bitOffset: PositiveInteger [0..1]</code> (präzise Bitposition innerhalb des jeweiligen PDU-Payloads; dient als Identitätsbeitrag).</li>\n<li><strong><code>DiagnosticParameter</code>:</strong> Konkrete Spezialisierung von <code>DiagnosticAbstractParameter</code> als Träger für Request- und Response-Parameter der Subfunktionen.</li>\n<li><strong><code>DiagnosticDataElement</code> (<code>DiagnosticServiceMappingDiagTarget</code>, <code>Identifiable</code>):</strong> Typdefinition des Dateninhalts, implementiert sowohl <code>DiagnosticServiceMappingDiagTarget</code> als auch <code>Identifiable</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticRoutineControl</code> $\\rightarrow$ <code>DiagnosticRoutine</code>:</strong> Multiplizität <code>0..1</code> (<code>+routine</code>), referenziert optional die adressierte Routine.</li>\n<li><strong><code>DiagnosticRoutine</code> $\\rightarrow$ Subfunktionen:</strong></li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStartRoutine</code> (<code>+start</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticStopRoutine</code> (<code>+stop</code>).</li>\n<li>Komposition <code>0..1</code> zu <code>DiagnosticRequestRoutineResults</code> (<code>+requestResult</code>).</li>\n<li><strong>Subfunktionen $\\rightarrow$ <code>DiagnosticParameter</code>:</strong></li>\n<li><code>DiagnosticStartRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticStopRoutine</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><code>DiagnosticRequestRoutineResults</code> kompositioniert <code>+request 0..<em></code> und <code>+response 0..</em></code>.</li>\n<li><strong><code>DiagnosticAbstractParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>:</strong></li>\n<li>Komposition mit Multiplizität <code>0..1</code> (<code>+dataElement</code>), markiert mit <code>«atpVariation, atpSplitable»</code> und annotiert mit Tag <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsstrukturen, determiniert jedoch direkt die UDS-Laufzeitabläufe im DCM:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> DCM empfängt Request <code>0x31 &lt;Subfunction&gt; &lt;RID_High&gt; &lt;RID_Low&gt; [&lt;routineControlOptionRecord&gt;]</code>.</li>\n<li><strong>Autorisierungsprüfung (Dsl/Dsd):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Validierung gegen <code>DiagnosticAccessPermission</code> (aktuelle Session/SecurityLevel). Bei Fehlschlag: NRC <code>0x7F</code> (<em>ServiceNotSupportedInActiveSession</em>) oder <code>0x33</code> (<em>SecurityAccessDenied</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Subfunktions-Dispatching (Dsp):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auflösung des RID (<code>DiagnosticRoutine.id</code>).</li>\n<li>Verifikation, ob die angeforderte Subfunktion (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) im Metamodell für diese Routine instantiiert ist (<code>+start</code>, <code>+stop</code>, <code>+requestResult</code>). Ist das Element nicht modelliert: NRC <code>0x12</code> (<em>SubFunctionNotSupported</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Parameter-Dekodierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parsen des Payloads anhand der sortierten Liste von <code>DiagnosticParameter.bitOffset</code>. Validierung der Länge gegen <code>DiagnosticDataElement.maxNumberOfElements</code>. Bei Über-/Unterlänge: NRC <code>0x13</code> (<em>IncorrectMessageLengthOrInvalidFormat</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikations-Aufruf (SW-C Interface):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchroner oder synchroner RTE-Callout an die zuständige Applikations-Softwarekomponente via Client-Server-Interface (<code>RoutineServices_&lt;RoutineName&gt;</code> mit den Operationen <code>Start</code>, <code>Stop</code>, <code>RequestResults</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response-Serialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Rückmeldung der SW-C (<code>E_OK</code> mit Rückgabewerten oder Application Error / NRC).</li>\n<li>Packen der <code>DiagnosticParameter</code> (<code>+response 0..*</code>) an die definierten <code>bitOffset</code>-Positionen in das positive Antworttelegramm <code>0x71 &lt;Subfunction&gt; &lt;RID&gt; [&lt;routineStatusRecord&gt;]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Stack-Konfiguration (Dcm):</strong></li>\n<li>DEXT-Generatoren überführen dieses Modell 1:1 in <code>DcmDspRoutine</code>, <code>DcmDspRoutineInfo</code>, <code>DcmDspStartRoutine</code>, <code>DcmDspStopRoutine</code> und <code>DcmDspRequestResultRoutine</code>.</li>\n<li>Entwickler müssen sicherstellen, dass nicht-modellierte Subfunktionen (Kardinalität <code>0</code>) im BSW-Konfigurator deaktiviert werden, um fehlerhafte NRC-Rückgaben zu vermeiden.</li>\n<li><strong>API- & Interface-Vertrag (RTE / SW-C):</strong></li>\n<li>Aus den <code>DiagnosticParameter</code>-Listen leitet der BSW-Generator die Funktionssignaturen für die Server-Runnables ab:</li>\n<li><code>Std_ReturnType &lt;SWC&gt;_StartRoutine(&lt;In-Params...&gt;, Dcm_OpStatusType OpStatus, &lt;Out-Params...&gt;, Dcm_NegativeResponseCodeType *ErrorCode)</code></li>\n<li>Dynamische Längen (<code>arraySizeSemantics == variableSize</code>) erfordern zwingend Längen-Pointer in der C-API.</li>\n<li><strong>Speicher- und Alignment-Constraints:</strong></li>\n<li>Durch <code>bitOffset</code> können ungerichtete Byte-/Bitgrenzen entstehen. Auf Architekturen ohne unaligned Access (z. B. bestimmte TriCore/ARM-Derivate) müssen Serialisierungs- und Kopierroutinen im DCM-Stub byteweise Shiften statt Casten, um Bus-/Trap-Exceptions zu verhindern.</li>\n<li><strong>Variantenmanagement (<code>«atpVariation»</code>):</strong></li>\n<li>Die RID-Vergabe (<code>id</code>) sowie die Zuweisung von <code>DiagnosticDataElement</code> sind variantenabhängig. Bei Post-Build- oder Pre-Compile-Varianten müssen die generierten PDU-Puffer auf die maximale Ausprägung (<code>maxNumberOfElements</code>) dimensioniert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-d80d80c7f7873f94", "to": "FIG-67fbdcbf06dacca7", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticAccessPermission</code>: Klasse sowie Assoziationen <code>+accessPermission 0..1</code> von <code>DiagnosticServiceClass</code> und <code>DiagnosticServiceInstance</code> entfernt.</li>\n<li><code>DiagnosticRoutine</code>: Optionales Attribut <code>routineInfo: PositiveInteger [0..1]</code> ergänzt.</li>\n<li><code>DiagnosticStartRoutine</code>, <code>DiagnosticStopRoutine</code>, <code>DiagnosticRequestRoutineResults</code>: Spezialisieren nun <code>DiagnosticRoutineSubfunction</code> anstelle von <code>Identifiable</code>.</li>\n</ul>"}, {"from": "FIG-67fbdcbf06dacca7", "to": "FIG-f4c1bc1c43c7d939", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticRequestRoutineResults</code>: Komposition <code>+request 0..*</code> zu <code>DiagnosticParameter</code> ergänzt.</li>\n<li><code>DiagnosticDataElement</code>: Attribut <code>scalingInfoSize: PositiveInteger [0..1]</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-f4c1bc1c43c7d939", "to": "FIG-e97877f6c18b29d1", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticServiceClass</code>: Attribut <code>accessPermissionValidity: DiagnosticAccessPermissionValidityEnum</code> entfernt.</li>\n<li><code>DiagnosticRoutineControl</code>: Multiplizität der Neudefinition <code>+routineControlClass</code> von <code>1 {redefines serviceClass}</code> auf <code>0..1 {redefines serviceClass}</code> geändert.</li>\n<li><code>DiagnosticRoutine</code>: Attribut <code>id</code> von <code>PositiveInteger</code> auf optional <code>PositiveInteger [0..1]</code> geändert.</li>\n<li><code>DiagnosticParameter</code>: Attribut <code>bitOffset</code> mit Stereotyp <code>«atpIdentityContributor»</code> versehen und von <code>PositiveInteger</code> auf optional <code>PositiveInteger [0..1]</code> geändert.</li>\n<li><code>DiagnosticParameter</code> $\\rightarrow$ <code>DiagnosticDataElement</code>: Multiplizität der Komposition <code>+dataElement</code> von <code>1</code> auf <code>0..1</code> gelockert; Tag <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-e97877f6c18b29d1", "to": "FIG-0fe370724b3d43d5", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticDataElement</code>: Attribute <code>arraySizeSemantics</code>, <code>maxNumberOfElements</code> und <code>scalingInfoSize</code> entfernt.</li>\n<li><code>DiagnosticDataElement</code>: Layout von unterhalb nach rechts neben <code>DiagnosticParameter</code> verschoben.</li>\n</ul>"}, {"from": "FIG-0fe370724b3d43d5", "to": "FIG-cd0e7a48104744c7", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticRoutineControl</code>: Multiplizität der Assoziation <code>+routine</code> von <code>1</code> auf optional <code>0..1</code> gelockert.</li>\n<li><code>DiagnosticAbstractParameter</code>: Neue abstrakte Basisklasse mit Attributen <code>parameterSize: PositiveInteger [0..1]</code> und <code>«atpIdentityContributor» + bitOffset: PositiveInteger [0..1]</code> eingeführt; Komposition <code>+dataElement 0..1</code> dorthin verlagert.</li>\n<li><code>DiagnosticParameter</code>: Spezialisiert nun <code>DiagnosticAbstractParameter</code>; Attribut <code>bitOffset</code> und Komposition <code>+dataElement</code> in die Basisklasse ausgelagert.</li>\n<li><code>DiagnosticDataElement</code>: Spezialisiert/implementiert nun zusätzlich <code>DiagnosticServiceMappingDiagTarget</code> (neben <code>Identifiable</code>).</li>\n</ul>"}, {"from": "FIG-cd0e7a48104744c7", "to": "FIG-f0110b9ca2edc883", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f0110b9ca2edc883", "to": "FIG-2fccf97431013370", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2fccf97431013370", "to": "FIG-7a3bd921c1b98c1c", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
